import React, { useEffect, useRef, useState } from 'react';
import { BrowserMultiFormatReader, NotFoundException } from '@zxing/library';
import {
    Box,
    Select,
    MenuItem,
    FormControl,
    InputLabel,
} from "@material-ui/core";
import "./scan.css";
// import { LocalizeContext } from "i18n";
// import { useHistory } from "react-router-dom";

const QRScanner = ({ open }) => {
    const videoRef = useRef(null);
    const [cameras, setCameras] = useState([]);
    const [selectedCamera, setSelectedCamera] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    const codeReaderRef = useRef(null);
    // const i18n = React.useContext(LocalizeContext);
    // const history = useHistory();

    // 检测后置摄像头的方法
    const detectBackCamera = async () => {
        try {
            // 先尝试使用环境模式（后置摄像头）
            const stream = await navigator.mediaDevices.getUserMedia({
                video: { facingMode: 'environment' }
            });

            const videoTrack = stream.getVideoTracks()[0];
            const settings = videoTrack.getSettings();

            // 停止流
            videoTrack.stop();

            return settings.deviceId;
        } catch (error) {
            console.log('无法获取后置摄像头，尝试用户模式:', error);

            // 如果环境模式失败，尝试用户模式（前置摄像头）
            try {
                const stream = await navigator.mediaDevices.getUserMedia({
                    video: { facingMode: 'user' }
                });

                const videoTrack = stream.getVideoTracks()[0];
                const settings = videoTrack.getSettings();

                videoTrack.stop();
                return settings.deviceId;
            } catch (userError) {
                console.log('无法获取任何摄像头:', userError);
                return null;
            }
        }
    };

    // 获取可用摄像头并选择后置摄像头
    useEffect(() => {
        if (!open) return;

        const codeReader = new BrowserMultiFormatReader();
        codeReaderRef.current = codeReader;

        const getCameras = async () => {
            setIsLoading(true);

            try {

                // 先尝试检测后置摄像头
                const backCameraId = await detectBackCamera();

                // 获取所有摄像头设备
                const videoInputDevices = await codeReader.listVideoInputDevices();

                if (videoInputDevices.length > 0) {
                    setCameras(videoInputDevices);

                    let defaultCameraId;

                    if (backCameraId) {
                        // 使用检测到的后置摄像头
                        defaultCameraId = backCameraId;
                    } else {
                        // 如果无法检测，尝试通过标签识别
                        const backCamera = videoInputDevices.find(device =>
                            device.label.toLowerCase().includes('back') ||
                            device.label.toLowerCase().includes('rear') ||
                            device.label.toLowerCase().includes('environment')
                        );
                        defaultCameraId = backCamera?.deviceId || videoInputDevices[0]?.deviceId;
                    }

                    setSelectedCamera(defaultCameraId);
                    // setIsLoading(false);
                }
            } catch (err) {
                console.error('摄像头访问错误:', err);
            } finally {
                setIsLoading(false);
            }
        };

        getCameras();

        return () => {
            codeReader.reset();
        };
    }, [open]);

    // 处理摄像头选择和开始扫描
    useEffect(() => {
        if (!selectedCamera || !open) return;

        const codeReader = codeReaderRef.current;
        const videoElement = videoRef.current;

        const startScanning = async () => {
            try {
                await codeReader.decodeFromVideoDevice(
                    selectedCamera,
                    videoElement,
                    (result, err) => {
                        if (result) {
                            alert(`扫描结果: ${result.getText()}`);
                            // const url = result.getText().split("query=")[1];
                            // history.push(`/itf_retrievalPage/${url}`)
                            // setOpen(false)
                        } else if (err) {
                            if (!(err instanceof NotFoundException)) {
                                console.error('扫描错误:', err);
                            }
                        }
                    }
                );
            } catch (err) {
                console.error('扫描过程出错:', err);
            } finally {
                setIsLoading(false);
            }
        };

        startScanning();

        return () => {
            codeReader.reset();
        };
    }, [selectedCamera, open, isLoading, setIsLoading]);

    const handleCameraChange = (event) => {
        setSelectedCamera(event.target.value);
    };

    const frameStyle = {
        position: 'absolute',
        top: '25%',
        left: '15%',
        width: '70%',
        height: '50%',
        border: '2px solid rgb(220, 2, 2)',
        boxSizing: 'border-box',
        zIndex: 3,
    };

    if (isLoading) {
        return <Box mt={10} style={{ textAlign: "center" }}>{  `加载中` }...</Box>
    };

    return (
        <Box className="video-container">
            <Box>
                <FormControl className="cameraSelect" variant="outlined">
                    <InputLabel>选择摄像头</InputLabel>
                    <Select
                        value={selectedCamera || ''}
                        onChange={handleCameraChange}
                        label="选择摄像头"
                    >
                        {cameras.map((camera) => (
                            <MenuItem key={camera.deviceId} value={camera.deviceId}>
                                {camera.label || `摄像头 ${camera.deviceId.slice(0, 8)}...`}
                            </MenuItem>
                        ))}
                    </Select>
                </FormControl>
                <video ref={videoRef}
                    playsInline
                    autoPlay
                    width="100%"
                    height="auto"
                ></video>
                <div className="overlay">
                    {/* 遮罩层 */}
                    <div className="mask  topMask" />
                    <div className="mask bttomMask" />
                    <div className="mask leftMask" />
                    <div className="mask rightMask" />
                    {/* 扫描框 */}
                    <div style={frameStyle}>
                        <div className="scanLine"></div>
                    </div>
                </div>
            </Box>
        </Box>
    );
};

export default QRScanner;